import java.util.*;
import java.io.*;

public class Main {
    static class MinCostFlow {
        int nodeCount;
        long INF = (long)1e9;
        long[] priority, potential, currentFlow;
        int[] prevEdge, prevNode;
        PriorityQueue<long[]> pq;
        static class Edge {
            int to, rev;
            long flow, capacity;
            long cost;
            Edge(int to, int rev, long flow, long capacity, long cost) {
                this.to = to;
                this.rev = rev;
                this.flow = flow;
                this.capacity = capacity;
                this.cost = cost;
            }
        }
        List<List<Edge>> graph;

        MinCostFlow(int n) {
            nodeCount = n;
            priority = new long[n];
            potential = new long[n];
            currentFlow = new long[n];
            prevEdge = new int[n];
            prevNode = new int[n];
            pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            graph = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                graph.add(new ArrayList<>());
            }
        }

        void addEdge(int s, int t, long cap, long cst) {
            graph.get(s).add(new Edge(t, graph.get(t).size(), 0, cap, cst));
            graph.get(t).add(new Edge(s, graph.get(s).size() - 1, 0, 0, -cst));
        }

        long[] computeFlow(int s, int t) {
            long totalFlow = 0;
            long totalCost = 0;
            while (true) {
                Arrays.fill(priority, INF);
                priority[s] = 0;
                currentFlow[s] = INF;
                pq.clear();
                pq.offer(new long[]{0, s});
                while (!pq.isEmpty()) {
                    long[] current = pq.poll();
                    long dist = current[0];
                    int u = (int) current[1];
                    if (dist != priority[u]) continue;
                    for (int i = 0; i < graph.get(u).size(); i++) {
                        Edge e = graph.get(u).get(i);
                        int v = e.to;
                        if (e.capacity <= e.flow) continue;
                        long newPriority = priority[u] + e.cost + potential[u] - potential[v];
                        if (priority[v] > newPriority) {
                            priority[v] = newPriority;
                            pq.offer(new long[]{newPriority, v});
                            prevNode[v] = u;
                            prevEdge[v] = i;
                            currentFlow[v] = Math.min(currentFlow[u], e.capacity - e.flow);
                        }
                    }
                }
                if (priority[t] == INF) break;
                for (int i = 0; i < nodeCount; i++) {
                    potential[i] += priority[i];
                }
                long delta = Math.min(currentFlow[t], INF - totalFlow);
                totalFlow += delta;
                for (int v = t; v != s; v = prevNode[v]) {
                    Edge e = graph.get(prevNode[v]).get(prevEdge[v]);
                    e.flow += delta;
                    graph.get(v).get(e.rev).flow -= delta;
                    totalCost += delta * e.cost;
                }
            }
            return new long[]{totalFlow, totalCost};
        }
    }

    public static void main(String[] args) throws IOException {
        final int T = 150;
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int N = n * T;
        MinCostFlow mcf = new MinCostFlow(N + 2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                mcf.addEdge(i * T + j, i * T + j + 1, (long)1e9, c);
            }
        }
        for (int i = 0; i < T; i++) {
            mcf.addEdge(i, N + 1, (long)1e9, 0);
        }
        int[] xArr = new int[k];
        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(br.readLine()) - 1;
            xArr[i] = x;
            mcf.addEdge(N, x * T, 1, 0);
        }
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            for (int j = 0; j < T - 1; j++) {
                int cur = 1;
                for (int _ = 0; _ < k; _++) {
                    mcf.addEdge(x * T + j, y * T + j + 1, 1, cur * d + c);
                    mcf.addEdge(y * T + j, x * T + j + 1, 1, cur * d + c);
                    cur += 2;
                }
            }
        }
        long[] result = mcf.computeFlow(N, N + 1);
        // Assert that total flow equals k
        if (result[0] != k) {
            throw new AssertionError();
        }
        System.out.println(result[1]);
    }
}
